def permanent_ryser(matrix):
    n = len(matrix)
    # Ryser's formula: perm(A) = (-1)^n * sum_{S subset of [n]} (-1)^|S| * prod_{i=1}^{n} sum_{j in S} a_{ij}
    total = 0
    for mask in range(1, 1 << n):
        # S = set of columns in mask
        bits = bin(mask).count('1')
        prod = 1
        for i in range(n):
            s = 0
            for j in range(n):
